$guard$;
ALTER POLICY shop_media_owner_insert ON storage.objects WITH CHECK (bucket_id = 'shop-media'
  AND (storage.foldername(objects.name))[2] = 'branding'
  AND (storage.foldername(objects.name))[3] IN ('logo', 'cover')
  AND owner_id = (SELECT auth.uid()::text)
  AND EXISTS (
    SELECT 1 FROM public.storefronts AS storefront
    WHERE storefront.id::text = (storage.foldername(objects.name))[1]
      AND storefront.owner_id = (SELECT auth.uid())
  ));
ALTER POLICY shop_media_owner_update ON storage.objects USING (false) WITH CHECK (false);
ALTER POLICY shop_media_owner_delete ON storage.objects USING (false);
